class Solution:
    def checkEqualPartitions(self, nums: List[int], target: int) -> bool:
        n = len(nums)
        for mask in range(1, (1 << n) - 1):
            p = q = 1
            for i in range(n):
                if mask >> i & 1:
                    p *= nums[i]
                else:
                    q *= nums[i]
                if p > target or q > target:
                    break
            else:
                if p == target and q == target:
                    return True
        return False

