class Solution {
public:
    bool checkEqualPartitions(vector<int>& nums, long long target) {
        int n = nums.size();
        for (int mask = 1; mask < (1 << n) - 1; mask++) {
            long long p = 1, q = 1; bool ok = true;
            for (int i = 0; i < n && ok; i++) {
                if (mask >> i & 1) { if (p > target / nums[i]) ok = false; else p *= nums[i]; }
                else { if (q > target / nums[i]) ok = false; else q *= nums[i]; }
            }
            if (ok && p == target && q == target) return true;
        }
        return false;
    }
};

