class Solution {
    private boolean dfs(int[] nums, int i, long p, long q, long target) {
        if (p > target || q > target) return false;
        if (i == nums.length) return p == target && q == target;
        return dfs(nums, i + 1, p * nums[i], q, target) || dfs(nums, i + 1, p, q * nums[i], target);
    }
    public boolean checkEqualPartitions(int[] nums, long target) {
        Arrays.sort(nums);
        for (int l = 0, r = nums.length - 1; l < r; l++, r--) { int t = nums[l]; nums[l] = nums[r]; nums[r] = t; }
        return dfs(nums, 0, 1, 1, target);
    }
}

